ee:message.ee:set-payload:
%dw 2.0
output application/json
var outcomes = payload map ((m) -> m.payload)
---
{
	quotes: (outcomes filter ((o) -> o.quote != null)) map ((o) -> o.quote),
	noResponse: (outcomes filter ((o) -> o.quote == null)) map ((o) -> { abv: o.abv, externalId: o.externalId, reason: o.reason })
}
